'use strict';
// node-fetch 2.x's optional charset conversion: `encoding` is an optional
// peer dependency, loaded if present and silently skipped otherwise.
let convert;
try {
  convert = require('encoding').convert;
} catch (e) {}

function requireOutcome() {
  try {
    require('encoding');
    return 'loaded';
  } catch (e) {
    return e.code + ': ' + e.message.split('\n')[0];
  }
}

function textConverted(text) {
  if (typeof convert !== 'function') {
    throw new Error('The package `encoding` must be installed to use the textConverted() function');
  }
  return convert(text, 'UTF-8', 'latin1').toString();
}

function hasConverter() {
  return typeof convert === 'function';
}

module.exports = { textConverted, hasConverter, requireOutcome };
